package did

import (
	"crypto/ed25519"
	"encoding/base64"
	"encoding/hex"
	"fmt"
	"math/big"
	"strings"
	"time"
)

type Method string

const (
	MethodKNIRV Method = "knirv"
	MethodKey   Method = "key"
)

var (
	ErrDIDNotFound      = fmt.Errorf("did not found")
	ErrDIDDeactivated   = fmt.Errorf("did is deactivated")
	ErrUnsupportedMethod = fmt.Errorf("unsupported did method")
	ErrInvalidEncoding  = fmt.Errorf("invalid did encoding")
)

type DIDStore interface {
	Get(did string) (*DIDDocument, error)
	Put(doc *DIDDocument) error
	Deactivate(did string) error
}

const ed25519Multicodec byte = 0xed

var base58Alphabet = []byte("REDACTED")

var base58Index = func() map[byte]int {
	idx := make(map[byte]int, len(base58Alphabet))
	for i, c := range base58Alphabet {
		idx[c] = i
	}
	return idx
}()

func base58Decode(input string) ([]byte, error) {
	if len(input) == 0 {
		return nil, ErrInvalidEncoding
	}

	zero := big.NewInt(0)
	radix := big.NewInt(58)

	leadingZeros := 0
	for _, c := range input {
		if c == '1' {
			leadingZeros++
		} else {
			break
		}
	}

	total := big.NewInt(0)
	for _, c := range input {
		val, ok := base58Index[byte(c)]
		if !ok {
			return nil, fmt.Errorf("%w: invalid character %c", ErrInvalidEncoding, c)
		}
		total.Mul(total, radix)
		total.Add(total, big.NewInt(int64(val)))
	}

	decoded := total.Bytes()
	result := make([]byte, leadingZeros+len(decoded))
	copy(result[leadingZeros:], decoded)
	return result, nil
}

type Resolver struct {
	store DIDStore
}

func NewResolver(store DIDStore) *Resolver {
	return &Resolver{store: store}
}

func parseDID(did string) (method Method, id string, err error) {
	if !strings.HasPrefix(did, "did:") {
		return "", "", fmt.Errorf("%w: missing did: prefix", ErrInvalidEncoding)
	}
	rest := strings.TrimPrefix(did, "did:")
	parts := strings.SplitN(rest, ":", 2)
	if len(parts) < 2 || parts[0] == "" || parts[1] == "" {
		return "", "", fmt.Errorf("%w: malformed did", ErrInvalidEncoding)
	}

	switch parts[0] {
	case "knirv":
		return MethodKNIRV, parts[1], nil
	case "key":
		return MethodKey, parts[1], nil
	default:
		return "", "", fmt.Errorf("%w: %s", ErrUnsupportedMethod, parts[0])
	}
}

func (r *Resolver) Resolve(did string) (*DIDDocument, error) {
	method, id, err := parseDID(did)
	if err != nil {
		return nil, err
	}

	switch method {
	case MethodKNIRV:
		return r.resolveKNIRV(id)
	case MethodKey:
		return r.resolveKey(id)
	default:
		return nil, ErrUnsupportedMethod
	}
}

func (r *Resolver) Register(doc *DIDDocument) error {
	if doc.ID == "" {
		return fmt.Errorf("did document must have an id")
	}
	if !strings.HasPrefix(doc.ID, "did:knirv:") {
		return fmt.Errorf("only did:knirv: documents can be registered")
	}

	doc.Created = time.Now().UTC()
	doc.Updated = time.Now().UTC()

	return r.store.Put(doc)
}

func (r *Resolver) Deactivate(did string) error {
	method, id, err := parseDID(did)
	if err != nil {
		return err
	}
	if method != MethodKNIRV {
		return fmt.Errorf("only did:knirv: documents can be deactivated")
	}
	return r.store.Deactivate(id)
}

func (r *Resolver) resolveKNIRV(id string) (*DIDDocument, error) {
	did := "did:knirv:" + id
	doc, err := r.store.Get(did)
	if err != nil {
		return nil, err
	}
	if doc == nil {
		return nil, ErrDIDNotFound
	}
	return doc, nil
}

func (r *Resolver) resolveKey(encoded string) (*DIDDocument, error) {
	if len(encoded) < 2 {
		return nil, ErrInvalidEncoding
	}

	prefix := encoded[0]
	data := encoded[1:]

	var raw []byte
	switch prefix {
	case 'z':
		var err error
		raw, err = base58Decode(data)
		if err != nil {
			return nil, fmt.Errorf("base58 decode: %w", err)
		}
	case 'u':
		var err error
		raw, err = base64.URLEncoding.DecodeString(data)
		if err != nil {
			return nil, fmt.Errorf("base64url decode: %w", err)
		}
	case 'f':
		var err error
		raw, err = hex.DecodeString(data)
		if err != nil {
			return nil, fmt.Errorf("hex decode: %w", err)
		}
	default:
		return nil, fmt.Errorf("%w: unsupported multibase prefix %c", ErrInvalidEncoding, prefix)
	}

	if len(raw) < 1 {
		return nil, ErrInvalidEncoding
	}

	var pubKey []byte
	if raw[0] == ed25519Multicodec {
		if len(raw) != 33 {
			return nil, fmt.Errorf("%w: expected 33 bytes for ed25519 key (1+32), got %d", ErrInvalidEncoding, len(raw))
		}
		pubKey = raw[1:]
	} else {
		pubKey = raw
	}

	if len(pubKey) != ed25519.PublicKeySize {
		return nil, fmt.Errorf("%w: expected %d byte public key, got %d", ErrInvalidEncoding, ed25519.PublicKeySize, len(pubKey))
	}

	multibaseEncoded := string(prefix) + data

	did := "did:key:" + multibaseEncoded
	vmID := did + "#" + encoded[len(encoded)-8:]

	now := time.Now().UTC()
	return &DIDDocument{
		Context: []string{"https://www.w3.org/ns/did/v1"},
		ID:      did,
		VerificationMethod: []VerificationMethod{
			{
				ID:                 vmID,
				Type:               "Ed25519VerificationKey2020",
				Controller:         did,
				PublicKeyMultibase: multibaseEncoded,
			},
		},
		Authentication:  []string{vmID},
		AssertionMethod: []string{vmID},
		Created:         now,
		Updated:         now,
	}, nil
}

package routes

import (
	"encoding/json"
	"fmt"
	"net/http"
	"strings"
	"time"

	"github.com/knirvcorp/knirvoracle/internal/oracle/did"
)

func (r *OracleRoutes) handleDIDRegister(w http.ResponseWriter, req *http.Request) {
	if req.Method != http.MethodPost {
		http.Error(w, "Method not allowed", http.StatusMethodNotAllowed)
		return
	}

	var doc did.DIDDocument
	if err := json.NewDecoder(req.Body).Decode(&doc); err != nil {
		http.Error(w, fmt.Sprintf("Invalid request: %v", err), http.StatusBadRequest)
		return
	}

	resolver := r.oracle.GetDIDResolver()
	if err := resolver.Register(&doc); err != nil {
		http.Error(w, fmt.Sprintf("Registration failed: %v", err), http.StatusBadRequest)
		return
	}

	respondJSON(w, http.StatusCreated, doc)
}

func (r *OracleRoutes) handleDIDResolve(w http.ResponseWriter, req *http.Request) {
	if req.Method != http.MethodGet {
		http.Error(w, "Method not allowed", http.StatusMethodNotAllowed)
		return
	}

	didStr := strings.TrimPrefix(req.URL.Path, "/oracle/v3/did/")
	if didStr == "" {
		http.Error(w, "DID is required", http.StatusBadRequest)
		return
	}

	resolver := r.oracle.GetDIDResolver()
	doc, err := resolver.Resolve(didStr)
	if err != nil {
		http.Error(w, fmt.Sprintf("Resolution failed: %v", err), http.StatusNotFound)
		return
	}

	respondJSON(w, http.StatusOK, doc)
}

func (r *OracleRoutes) handleDIDDeactivate(w http.ResponseWriter, req *http.Request) {
	if req.Method != http.MethodPost {
		http.Error(w, "Method not allowed", http.StatusMethodNotAllowed)
		return
	}

	didStr := strings.TrimPrefix(req.URL.Path, "/oracle/v3/did/")
	didStr = strings.TrimSuffix(didStr, "/deactivate")

	if didStr == "" {
		http.Error(w, "DID is required", http.StatusBadRequest)
		return
	}

	resolver := r.oracle.GetDIDResolver()
	if err := resolver.Deactivate(didStr); err != nil {
		http.Error(w, fmt.Sprintf("Deactivation failed: %v", err), http.StatusBadRequest)
		return
	}

	respondJSON(w, http.StatusOK, map[string]interface{}{
		"status":    "deactivated",
		"deactivated_at": time.Now().UTC(),
	})
}

func (r *OracleRoutes) RegisterDIDRoutes(mux *http.ServeMux) {
	mux.HandleFunc("/oracle/v3/did/register", r.handleDIDRegister)
	mux.HandleFunc("/oracle/v3/did/", r.handleDIDResolve)
	mux.HandleFunc("/oracle/v3/did/", r.handleDIDDeactivate)
}

package identitybridge

import (
	"crypto/sha256"
	"encoding/hex"
	"fmt"
	"sync"
	"time"
)

type RevocationEntry struct {
	IdentityID string    `json:"identity_id"`
	NodeID     string    `json:"node_id"`
	Reason     string    `json:"reason"`
	RevokedAt  time.Time `json:"revoked_at"`
	RevokedBy  string    `json:"revoked_by"`
	ChainHash  string    `json:"chain_hash"`
}

type RevocationList struct {
	mu      sync.RWMutex
	entries []*RevocationEntry
	index   map[string]int
	tip     string
}

func NewRevocationList() *RevocationList {
	return &RevocationList{
		entries: make([]*RevocationEntry, 0),
		index:   make(map[string]int),
	}
}

func (rl *RevocationList) Revoke(identityID, nodeID, reason, revokedBy string) *RevocationEntry {
	rl.mu.Lock()
	defer rl.mu.Unlock()

	entry := &RevocationEntry{
		IdentityID: identityID,
		NodeID:     nodeID,
		Reason:     reason,
		RevokedAt:  time.Now().UTC(),
		RevokedBy:  revokedBy,
	}

	chainInput := rl.tip + entry.IdentityID + entry.NodeID + entry.Reason + entry.RevokedBy + entry.RevokedAt.String()
	hash := sha256.Sum256([]byte(chainInput))
	entry.ChainHash = hex.EncodeToString(hash[:])
	rl.tip = entry.ChainHash

	rl.index[identityID] = len(rl.entries)
	rl.entries = append(rl.entries, entry)

	return entry
}

func (rl *RevocationList) IsRevoked(identityID string) bool {
	rl.mu.RLock()
	defer rl.mu.RUnlock()
	_, ok := rl.index[identityID]
	return ok
}

func (rl *RevocationList) VerifyChain() error {
	rl.mu.RLock()
	defer rl.mu.RUnlock()

	if len(rl.entries) == 0 {
		return nil
	}

	var prevHash string
	for i, entry := range rl.entries {
		chainInput := prevHash + entry.IdentityID + entry.NodeID + entry.Reason + entry.RevokedBy + entry.RevokedAt.String()
		hash := sha256.Sum256([]byte(chainInput))
		computedHash := hex.EncodeToString(hash[:])

		if computedHash != entry.ChainHash {
			return fmt.Errorf("chain integrity violated at entry %d: expected hash %s, got %s", i, entry.ChainHash, computedHash)
		}
		prevHash = entry.ChainHash
	}
	return nil
}

func (rl *RevocationList) Export() []*RevocationEntry {
	rl.mu.RLock()
	defer rl.mu.RUnlock()

	result := make([]*RevocationEntry, len(rl.entries))
	copy(result, rl.entries)
	return result
}

func (rl *RevocationList) Len() int {
	rl.mu.RLock()
	defer rl.mu.RUnlock()
	return len(rl.entries)
}

func (rl *RevocationList) TipHash() string {
	rl.mu.RLock()
	defer rl.mu.RUnlock()
	return rl.tip
}

