package mcphardening

type SchemaValidator struct {
	schemas map[string]*ToolSchema
}

type ToolSchema struct {
	Name        string              `json:"name"`
	Description string              `json:"description"`
	InputSchema *JSONSchema         `json:"inputSchema"`
	OutputSchema *JSONSchema        `json:"outputSchema,omitempty"`
}

type JSONSchema struct {
	Type       string                `json:"type"`
	Properties map[string]*SchemaProp `json:"properties,omitempty"`
	Required   []string              `json:"required,omitempty"`
	Items      *JSONSchema           `json:"items,omitempty"`
}

type SchemaProp struct {
	Type        string              `json:"type"`
	Description string              `json:"description,omitempty"`
	Pattern     string              `json:"pattern,omitempty"`
	MinLength   int                 `json:"minLength,omitempty"`
	MaxLength   int                 `json:"maxLength,omitempty"`
	Minimum     float64             `json:"minimum,omitempty"`
	Maximum     float64             `json:"maximum,omitempty"`
	Enum        []string            `json:"enum,omitempty"`
	Properties  map[string]*SchemaProp `json:"properties,omitempty"`
	Items       *JSONSchema         `json:"items,omitempty"`
}

func NewSchemaValidator() *SchemaValidator {
	return &SchemaValidator{
		schemas: make(map[string]*ToolSchema),
	}
}

func (sv *SchemaValidator) RegisterSchema(schema *ToolSchema) {
	sv.schemas[schema.Name] = schema
}

func (sv *SchemaValidator) GetSchema(name string) (*ToolSchema, bool) {
	s, ok := sv.schemas[name]
	return s, ok
}

func (sv *SchemaValidator) ValidateArgs(toolName string, args map[string]interface{}) (bool, string) {
	schema, ok := sv.schemas[toolName]
	if !ok {
		return false, "no schema registered for tool: " + toolName
	}
	if schema.InputSchema == nil {
		return true, ""
	}
	for _, req := range schema.InputSchema.Required {
		if _, ok := args[req]; !ok {
			return false, "missing required argument: " + req
		}
	}
	return true, ""
}

package mcphardening

import (
	"regexp"
	"strings"
)

type InjectionDetector struct {
	patterns []*regexp.Regexp
}

var defaultInjectionPatterns = []string{
	`(?i)\bDROP\s+TABLE`,
	`(?i)\bDELETE\s+FROM`,
	`(?i)\bINSERT\s+INTO`,
	`(?i)\bEXEC\b`,
	`(?i)<script`,
	`(?i)javascript:`,
	`(?i)onerror\s*=`,
	`(?i)onload\s*=`,
	`(?i)\$\{.*\}`,
	`(?i)\|.*\bbash\b`,
	`(?i)\|.*\bsh\b`,
	`(?i)` + "`" + `[^` + "`" + `]*` + "`" + ``,
	`(?i)\brm\s+-rf`,
	`(?i)\bwget\s+`,
	`(?i)\bcurl\s+`,
}

func NewInjectionDetector() *InjectionDetector {
	patterns := make([]*regexp.Regexp, 0, len(defaultInjectionPatterns))
	for _, p := range defaultInjectionPatterns {
		patterns = append(patterns, regexp.MustCompile(p))
	}
	return &InjectionDetector{patterns: patterns}
}

func (id *InjectionDetector) Detect(value string) (bool, string) {
	for _, pat := range id.patterns {
		if pat.MatchString(value) {
			return true, pat.String()
		}
	}
	return false, ""
}

func (id *InjectionDetector) Sanitize(value string) string {
	for _, pat := range id.patterns {
		if pat.MatchString(value) {
			return strings.Repeat("*", len(value))
		}
	}
	return value
}

func (id *InjectionDetector) ScanArguments(args map[string]interface{}) []string {
	var flagged []string
	for key, val := range args {
		str, ok := val.(string)
		if !ok {
			continue
		}
		if detected, _ := id.Detect(str); detected {
			flagged = append(flagged, key)
		}
	}
	return flagged
}

