 		if wsSvc, wsErr := dve_workspace.NewDVEService(teeSecurityService, dataEngine, virtualContainerManager, dveCfg); wsErr != nil {
 			log.Printf("Warning: Failed to initialize DVE OverlayFS workspace service: %v", wsErr)
