func base58Encode(input []byte) string {
	if len(input) == 0 {
		return ""
	}
	radix := 58
	zeroCount := 0
	for _, b := range input {
		if b == 0 {
			zeroCount++
		} else {
			break
		}
	}
	carry := make([]int, len(input))
	for i, b := range input {
		carry[i] = int(b)
	}
	var result []int
	for len(carry) > 0 {
		var remainder int
		var next []int
		for _, b := range carry {
			val := remainder*256 + b
			quotient := val / radix
			remainder = val % radix
			if len(next) > 0 || quotient > 0 {
				next = append(next, quotient)
			}
		}
		result = append(result, remainder)
		carry = next
	}
	for i := 0; i < zeroCount; i++ {
		result = append([]int{0}, result...)
	}
	output := make([]byte, len(result))
	for i, v := range result {
		output[i] = base58Alphabet[v]
	}
	return string(output)
}

